SET lock_timeout = '5s';
SET statement_timeout = '60s';

-- Companion of 20261116210000_exposures_rename.sql, generated by
-- `supabase db schema declarative sync` (pg-delta) from supabase/schemas/ and
-- left as generated below this header. What the rename could not carry:
--
--   * `exposures.instrument` (text, NOT NULL, default 'nircam': every existing
--     row is NIRCam's; a constant default is a catalog change, no rewrite),
--     its CHECK (nircam | acswfc | wfc3ir), and its place in the row identity:
--     UNIQUE (instrument, field, filter, filename).
--   * `exposures.mask_seed_hash` (nullable text): the content hash of the
--     pipeline-found mask a deploy seeded `mask_regions` from, so the seed
--     happens once and a reviewer's change or deletion is never undone.
--   * the progress view, now `exposure_review_progress` with the instrument
--     as its first grouping column (`nircam_reduction_progress` is dropped);
--   * `get_admin_exposures` / `get_admin_exposure_neighbors` with a trailing
--     `p_instrument` (NULL = every instrument, so a caller that predates it
--     still resolves), the instrument in the list order (field, instrument,
--     filter, filename) and, for the first, in the returned row;
--     `get_admin_exposure_facets` with an `instrument` facet;
--   * `get_admin_dashboard`, whose body names the table.

SET local check_function_bodies = off;

DROP VIEW "public"."nircam_reduction_progress";

ALTER TABLE "public"."exposures"
  DROP CONSTRAINT "exposures_unique";

DROP FUNCTION "public"."get_admin_exposure_neighbors"(integer, text, text, text, text, text, text, text, text, integer, text);

DROP FUNCTION "public"."get_admin_exposures"(text, text, text, text, text, text, text, text, integer, integer, text);

ALTER TABLE "public"."exposures"
  ADD COLUMN "instrument" text NOT NULL DEFAULT 'nircam'::text;

ALTER TABLE "public"."exposures"
  ADD COLUMN "mask_seed_hash" text;

CREATE OR REPLACE FUNCTION public.get_admin_dashboard()
  RETURNS jsonb
  LANGUAGE plpgsql
  STABLE
  SECURITY DEFINER
  SET search_path TO 'public', 'pg_temp'
  AS $function$
DECLARE
  v_is_admin boolean;
  v_deploy record;
  v_nircam record;
  v_objects record;
  v_access record;
  v_activity record;
BEGIN
  SELECT COALESCE(up.is_admin, false) INTO v_is_admin
  FROM user_profiles up WHERE up.user_id = auth.uid();
  IF NOT (COALESCE(v_is_admin, false) OR COALESCE(auth.role(), '') = 'service_role') THEN
    RAISE EXCEPTION 'Access denied: Admin privileges required';
  END IF;

  SELECT
    count(*) FILTER (WHERE d.status = 'draft') AS drafts,
    count(*) FILTER (WHERE d.deployed_at > now() - interval '7 days') AS deployed_7d,
    count(*) FILTER (WHERE d.status = 'published' AND d.cfpipe_version IS NOT NULL
                     AND d.cfpipe_version !~ '^[0-9]+\.[0-9]+\.[0-9]+$') AS unreleased_published,
    count(*) FILTER (WHERE d.status = 'published'
                     AND (d.cfpipe_version IS NULL OR d.crds_context IS NULL)) AS missing_provenance,
    count(DISTINCT d.crds_context) FILTER (WHERE d.status = 'published') AS crds_contexts,
    max(d.deployed_at) AS latest_deployed_at
  INTO v_deploy
  FROM deployments d;

  SELECT
    count(*) AS total,
    count(*) FILTER (WHERE ne.review_status = 'pending') AS pending,
    count(*) FILTER (WHERE ne.review_status IN ('approved', 'excluded')) AS done,
    count(*) FILTER (WHERE ne.correction = 'needed') AS needs_correction
  INTO v_nircam
  FROM exposures ne;

  -- Uninspected = quality 0 (the "Not Inspected" enum value) on a live object
  -- with a published spectrum; needs_review is the derived P3 flag.
  SELECT
    count(*) FILTER (WHERE o.is_active AND o.has_published_spectrum) AS published,
    count(*) FILTER (WHERE o.is_active AND o.has_published_spectrum
                     AND COALESCE(o.redshift_quality, 0) = 0) AS uninspected,
    count(*) FILTER (WHERE o.is_active AND o.needs_review) AS needs_review
  INTO v_objects
  FROM objects o;

  SELECT count(*) AS pending, min(r.created_at) AS oldest_at
  INTO v_access
  FROM inspection_access_requests r
  WHERE r.status = 'pending';

  -- comments.created_at and flag_audit_log.changed_at are naive UTC, so the
  -- window compares against now() AT TIME ZONE 'utc'.
  SELECT
    (SELECT count(*) FROM flag_audit_log f
     WHERE f.changed_at > (now() AT TIME ZONE 'utc') - interval '7 days') AS inspections_7d,
    (SELECT count(DISTINCT f.user_id) FROM flag_audit_log f
     WHERE f.user_id IS NOT NULL
       AND f.changed_at > (now() AT TIME ZONE 'utc') - interval '7 days') AS inspectors_7d,
    (SELECT count(*) FROM comments c
     WHERE NOT c.is_deleted
       AND c.created_at > (now() AT TIME ZONE 'utc') - interval '7 days') AS comments_7d
  INTO v_activity;

  RETURN jsonb_build_object(
    'generated_at', now(),
    -- Live deploy leases; `stale` is the dr_readiness rule (heartbeat older
    -- than deploy_lease_ttl()).
    'leases', (
      SELECT COALESCE(jsonb_agg(jsonb_build_object(
          'scope_type', s.scope_type,
          'scope_key', s.scope_key,
          'since', s.in_progress_since,
          'heartbeat_at', s.heartbeat_at,
          'host', s.in_progress_host,
          'actor_name', up.full_name,
          'stale', COALESCE(s.heartbeat_at, s.in_progress_since) < now() - deploy_lease_ttl())
        ORDER BY s.in_progress_since), '[]'::jsonb)
      FROM deploy_scope_state s
      LEFT JOIN user_profiles up ON up.user_id = s.in_progress_by
      WHERE s.in_progress_since IS NOT NULL),
    'deployments', jsonb_build_object(
      'drafts', v_deploy.drafts,
      'deployed_7d', v_deploy.deployed_7d,
      'unreleased_published', v_deploy.unreleased_published,
      'missing_provenance', v_deploy.missing_provenance,
      'crds_contexts', v_deploy.crds_contexts,
      'latest_deployed_at', v_deploy.latest_deployed_at),
    'review', jsonb_build_object(
      'nircam', jsonb_build_object(
        'total', v_nircam.total,
        'pending', v_nircam.pending,
        'done', v_nircam.done,
        'needs_correction', v_nircam.needs_correction,
        'top', (
          SELECT COALESCE(jsonb_agg(jsonb_build_object(
              'field', t.field, 'filter', t.filter, 'pending', t.pending)
            ORDER BY t.pending DESC, t.field, t.filter), '[]'::jsonb)
          FROM (SELECT ne.field, ne.filter, count(*) AS pending
                FROM exposures ne
                WHERE ne.review_status = 'pending'
                GROUP BY ne.field, ne.filter
                ORDER BY count(*) DESC, ne.field, ne.filter
                LIMIT 4) t)),
      'objects', jsonb_build_object(
        'published', v_objects.published,
        'uninspected', v_objects.uninspected,
        'needs_review', v_objects.needs_review,
        'top', (
          SELECT COALESCE(jsonb_agg(jsonb_build_object(
              'field', t.field, 'uninspected', t.uninspected)
            ORDER BY t.uninspected DESC, t.field), '[]'::jsonb)
          FROM (SELECT o.field, count(*) AS uninspected
                FROM objects o
                WHERE o.is_active AND o.has_published_spectrum
                  AND COALESCE(o.redshift_quality, 0) = 0
                GROUP BY o.field
                ORDER BY count(*) DESC, o.field
                LIMIT 4) t))),
    'access', jsonb_build_object(
      'pending_requests', v_access.pending,
      'oldest_request_at', v_access.oldest_at),
    'activity', jsonb_build_object(
      'inspections_7d', v_activity.inspections_7d,
      'inspectors_7d', v_activity.inspectors_7d,
      'comments_7d', v_activity.comments_7d),
    'sync_snapshot', (
      SELECT to_jsonb(x) FROM (
        SELECT s.status, s.started_at, s.completed_at, s.error
        FROM sync_snapshots s
        ORDER BY s.created_at DESC
        LIMIT 1) x)
  );
END;
$function$;

CREATE OR REPLACE FUNCTION public.get_admin_exposure_facets()
  RETURNS TABLE (
    kind  text,
    value text
  )
  LANGUAGE plpgsql
  STABLE
  SET search_path TO 'public', 'pg_temp'
  AS $function$
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Access denied: Admin privileges required';
  END IF;

  RETURN QUERY
  SELECT 'field'::text, e.field FROM exposures e GROUP BY e.field
  UNION ALL
  SELECT 'instrument'::text, e.instrument FROM exposures e GROUP BY e.instrument
  UNION ALL
  SELECT 'filter'::text, e.filter FROM exposures e GROUP BY e.filter
  UNION ALL
  SELECT 'detector'::text, e.detector FROM exposures e GROUP BY e.detector
  UNION ALL
  SELECT 'stage'::text, e.stage FROM exposures e GROUP BY e.stage
  ORDER BY 1, 2;
END;
$function$;

CREATE OR REPLACE FUNCTION public.get_admin_exposure_neighbors (
  p_current_id     integer,
  p_field          text    DEFAULT NULL::text,
  p_filter         text    DEFAULT NULL::text,
  p_detector       text    DEFAULT NULL::text,
  p_review_status  text    DEFAULT NULL::text,
  p_stage          text    DEFAULT NULL::text,
  p_correction     text    DEFAULT NULL::text,
  p_sort_column    text    DEFAULT 'filename'::text,
  p_sort_direction text    DEFAULT 'asc'::text,
  p_window         integer DEFAULT 3,
  p_search         text    DEFAULT NULL::text,
  p_instrument     text    DEFAULT NULL::text
)
  RETURNS TABLE (
    id           integer,
    nav_position bigint,
    total_count  bigint
  )
  LANGUAGE plpgsql
  STABLE
  SET search_path TO 'public', 'pg_temp'
  AS $function$
DECLARE
  v_window integer := LEAST(GREATEST(COALESCE(p_window, 3), 1), 25);
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Access denied: Admin privileges required';
  END IF;
  IF p_sort_direction NOT IN ('asc', 'desc') THEN p_sort_direction := 'asc'; END IF;
  IF p_sort_column NOT IN ('filename', 'field', 'instrument', 'filter', 'detector', 'stage',
                           'review_status', 'date_obs', 'updated_at') THEN
    p_sort_column := 'filename';
  END IF;

  RETURN QUERY
  WITH ranked AS (
    SELECT e.id AS exp_id,
           row_number() OVER (ORDER BY
             -- Keep in lockstep with get_admin_exposures.
             CASE WHEN p_sort_column = 'filename' AND p_sort_direction = 'asc'  THEN e.field END ASC,
             CASE WHEN p_sort_column = 'filename' AND p_sort_direction = 'asc'  THEN e.instrument END ASC,
             CASE WHEN p_sort_column = 'filename' AND p_sort_direction = 'asc'  THEN e.filter END ASC,
             CASE WHEN p_sort_column = 'filename' AND p_sort_direction = 'asc'  THEN e.filename END ASC,
             CASE WHEN p_sort_column = 'filename' AND p_sort_direction = 'desc' THEN e.field END DESC,
             CASE WHEN p_sort_column = 'filename' AND p_sort_direction = 'desc' THEN e.instrument END DESC,
             CASE WHEN p_sort_column = 'filename' AND p_sort_direction = 'desc' THEN e.filter END DESC,
             CASE WHEN p_sort_column = 'filename' AND p_sort_direction = 'desc' THEN e.filename END DESC,
             CASE WHEN p_sort_column = 'field' AND p_sort_direction = 'asc'  THEN e.field END ASC,
             CASE WHEN p_sort_column = 'field' AND p_sort_direction = 'desc' THEN e.field END DESC,
             CASE WHEN p_sort_column = 'instrument' AND p_sort_direction = 'asc'  THEN e.instrument END ASC,
             CASE WHEN p_sort_column = 'instrument' AND p_sort_direction = 'desc' THEN e.instrument END DESC,
             CASE WHEN p_sort_column = 'filter' AND p_sort_direction = 'asc'  THEN e.filter END ASC,
             CASE WHEN p_sort_column = 'filter' AND p_sort_direction = 'desc' THEN e.filter END DESC,
             CASE WHEN p_sort_column = 'detector' AND p_sort_direction = 'asc'  THEN e.detector END ASC,
             CASE WHEN p_sort_column = 'detector' AND p_sort_direction = 'desc' THEN e.detector END DESC,
             CASE WHEN p_sort_column = 'stage' AND p_sort_direction = 'asc'  THEN e.stage END ASC,
             CASE WHEN p_sort_column = 'stage' AND p_sort_direction = 'desc' THEN e.stage END DESC,
             CASE WHEN p_sort_column = 'review_status' AND p_sort_direction = 'asc'  THEN e.review_status END ASC,
             CASE WHEN p_sort_column = 'review_status' AND p_sort_direction = 'desc' THEN e.review_status END DESC,
             CASE WHEN p_sort_column = 'date_obs' AND p_sort_direction = 'asc'  THEN e.date_obs END ASC NULLS LAST,
             CASE WHEN p_sort_column = 'date_obs' AND p_sort_direction = 'desc' THEN e.date_obs END DESC NULLS LAST,
             CASE WHEN p_sort_column = 'updated_at' AND p_sort_direction = 'asc'  THEN e.updated_at END ASC NULLS LAST,
             CASE WHEN p_sort_column = 'updated_at' AND p_sort_direction = 'desc' THEN e.updated_at END DESC NULLS LAST,
             e.id ASC
           ) AS rn,
           count(*) OVER () AS n
    FROM exposures e
    WHERE (p_field IS NULL OR e.field = p_field)
      AND (p_instrument IS NULL OR e.instrument = p_instrument)
      AND (p_filter IS NULL OR e.filter = p_filter)
      AND (p_detector IS NULL OR e.detector = p_detector)
      AND (p_review_status IS NULL OR e.review_status = p_review_status)
      AND (p_stage IS NULL OR e.stage = p_stage)
        AND (p_correction IS NULL OR e.correction = p_correction)
        AND (p_search IS NULL OR p_search = '' OR e.filename ILIKE p_search)
  ),
  cur AS (
    SELECT r.rn AS rn0 FROM ranked r WHERE r.exp_id = p_current_id
  )
  SELECT r.exp_id, r.rn, r.n
  FROM ranked r, cur
  WHERE r.rn BETWEEN cur.rn0 - v_window AND cur.rn0 + v_window
  ORDER BY r.rn;
END;
$function$;

REVOKE ALL ON FUNCTION "public"."get_admin_exposure_neighbors"(integer, text, text, text, text, text, text, text, text, integer, text, text) FROM PUBLIC, "anon";

CREATE OR REPLACE FUNCTION public.get_admin_exposures (
  p_field          text    DEFAULT NULL::text,
  p_filter         text    DEFAULT NULL::text,
  p_detector       text    DEFAULT NULL::text,
  p_review_status  text    DEFAULT NULL::text,
  p_stage          text    DEFAULT NULL::text,
  p_correction     text    DEFAULT NULL::text,
  p_sort_column    text    DEFAULT 'filename'::text,
  p_sort_direction text    DEFAULT 'asc'::text,
  p_page           integer DEFAULT 1,
  p_page_size      integer DEFAULT 50,
  p_search         text    DEFAULT NULL::text,
  p_instrument     text    DEFAULT NULL::text
)
  RETURNS TABLE (
    id                integer,
    instrument        text,
    field             text,
    filter            text,
    detector          text,
    filename          text,
    visit             text,
    date_obs          timestamp without time zone,
    ra_center         double precision,
    dec_center        double precision,
    stage             text,
    review_status     text,
    correction        text,
    png_path          text,
    full_png_path     text,
    image_width       integer,
    image_height      integer,
    mask_regions      jsonb,
    notes             text,
    review_decided_at timestamp with time zone,
    created_at        timestamp without time zone,
    updated_at        timestamp without time zone,
    total_count       bigint
  )
  LANGUAGE plpgsql
  STABLE
  SET search_path TO 'public', 'pg_temp'
  AS $function$
DECLARE
  v_limit integer := LEAST(GREATEST(COALESCE(p_page_size, 50), 1), 200);
  v_offset integer := GREATEST(COALESCE(p_page, 1) - 1, 0) * LEAST(GREATEST(COALESCE(p_page_size, 50), 1), 200);
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Access denied: Admin privileges required';
  END IF;
  IF p_sort_direction NOT IN ('asc', 'desc') THEN p_sort_direction := 'asc'; END IF;
  IF p_sort_column NOT IN ('filename', 'field', 'instrument', 'filter', 'detector', 'stage',
                           'review_status', 'date_obs', 'updated_at') THEN
    p_sort_column := 'filename';
  END IF;

  RETURN QUERY
  SELECT e.id, e.instrument, e.field, e.filter, e.detector, e.filename, e.visit, e.date_obs,
         e.ra_center, e.dec_center, e.stage, e.review_status,
         e.correction, e.png_path, e.full_png_path, e.image_width,
         e.image_height, e.mask_regions, e.notes, e.review_decided_at,
         e.created_at, e.updated_at,
         count(*) OVER ()
  FROM exposures e
  WHERE (p_field IS NULL OR e.field = p_field)
    AND (p_instrument IS NULL OR e.instrument = p_instrument)
    AND (p_filter IS NULL OR e.filter = p_filter)
    AND (p_detector IS NULL OR e.detector = p_detector)
    AND (p_review_status IS NULL OR e.review_status = p_review_status)
    AND (p_stage IS NULL OR e.stage = p_stage)
    AND (p_correction IS NULL OR e.correction = p_correction)
    AND (p_search IS NULL OR p_search = '' OR e.filename ILIKE p_search)
  ORDER BY
    -- Keep in lockstep with get_admin_exposure_neighbors. The list order is
    -- (field, instrument, filter, filename): a field's instruments together.
    CASE WHEN p_sort_column = 'filename' AND p_sort_direction = 'asc'  THEN e.field END ASC,
    CASE WHEN p_sort_column = 'filename' AND p_sort_direction = 'asc'  THEN e.instrument END ASC,
    CASE WHEN p_sort_column = 'filename' AND p_sort_direction = 'asc'  THEN e.filter END ASC,
    CASE WHEN p_sort_column = 'filename' AND p_sort_direction = 'asc'  THEN e.filename END ASC,
    CASE WHEN p_sort_column = 'filename' AND p_sort_direction = 'desc' THEN e.field END DESC,
    CASE WHEN p_sort_column = 'filename' AND p_sort_direction = 'desc' THEN e.instrument END DESC,
    CASE WHEN p_sort_column = 'filename' AND p_sort_direction = 'desc' THEN e.filter END DESC,
    CASE WHEN p_sort_column = 'filename' AND p_sort_direction = 'desc' THEN e.filename END DESC,
    CASE WHEN p_sort_column = 'field' AND p_sort_direction = 'asc'  THEN e.field END ASC,
    CASE WHEN p_sort_column = 'field' AND p_sort_direction = 'desc' THEN e.field END DESC,
    CASE WHEN p_sort_column = 'instrument' AND p_sort_direction = 'asc'  THEN e.instrument END ASC,
    CASE WHEN p_sort_column = 'instrument' AND p_sort_direction = 'desc' THEN e.instrument END DESC,
    CASE WHEN p_sort_column = 'filter' AND p_sort_direction = 'asc'  THEN e.filter END ASC,
    CASE WHEN p_sort_column = 'filter' AND p_sort_direction = 'desc' THEN e.filter END DESC,
    CASE WHEN p_sort_column = 'detector' AND p_sort_direction = 'asc'  THEN e.detector END ASC,
    CASE WHEN p_sort_column = 'detector' AND p_sort_direction = 'desc' THEN e.detector END DESC,
    CASE WHEN p_sort_column = 'stage' AND p_sort_direction = 'asc'  THEN e.stage END ASC,
    CASE WHEN p_sort_column = 'stage' AND p_sort_direction = 'desc' THEN e.stage END DESC,
    CASE WHEN p_sort_column = 'review_status' AND p_sort_direction = 'asc'  THEN e.review_status END ASC,
    CASE WHEN p_sort_column = 'review_status' AND p_sort_direction = 'desc' THEN e.review_status END DESC,
    CASE WHEN p_sort_column = 'date_obs' AND p_sort_direction = 'asc'  THEN e.date_obs END ASC NULLS LAST,
    CASE WHEN p_sort_column = 'date_obs' AND p_sort_direction = 'desc' THEN e.date_obs END DESC NULLS LAST,
    CASE WHEN p_sort_column = 'updated_at' AND p_sort_direction = 'asc'  THEN e.updated_at END ASC NULLS LAST,
    CASE WHEN p_sort_column = 'updated_at' AND p_sort_direction = 'desc' THEN e.updated_at END DESC NULLS LAST,
    e.id ASC
  OFFSET v_offset LIMIT v_limit;
END;
$function$;

REVOKE ALL ON FUNCTION "public"."get_admin_exposures"(text, text, text, text, text, text, text, text, integer, integer, text, text) FROM PUBLIC, "anon";

ALTER TABLE "public"."exposures"
  ADD CONSTRAINT "exposures_instrument_check" CHECK ((instrument = ANY (ARRAY['nircam'::text, 'acswfc'::text, 'wfc3ir'::text])));

ALTER TABLE "public"."exposures"
  ADD CONSTRAINT "exposures_unique" UNIQUE (instrument, field, filter, filename);

CREATE VIEW "public"."exposure_review_progress" WITH (security_invoker=true) AS  SELECT instrument,
    field,
    filter,
    detector,
    count(*) AS total,
    count(*) FILTER (WHERE (review_status = 'pending'::text)) AS pending_review,
    count(*) FILTER (WHERE (review_status = 'approved'::text)) AS approved,
    count(*) FILTER (WHERE (review_status = 'excluded'::text)) AS excluded,
    count(*) FILTER (WHERE (mask_regions IS NOT NULL)) AS masked,
    count(*) FILTER (WHERE (correction = 'needed'::text)) AS needs_correction
   FROM public.exposures
  GROUP BY instrument, field, filter, detector;

REVOKE ALL ON TABLE "public"."exposure_review_progress" FROM "anon";

